--- header
Set a ThemeResource from code
--- xaml
<Grid x:Name="ThemeResourceFromCodeRoot">
    <Border x:Name="OneTimeLookupBorder">
        <TextBlock x:Name="OneTimeLookupText"
                   Text="A one-time resource lookup keeps the value from when it was read." />
    </Border>
    <Border x:Name="ThemeResourceBindingBorder" Grid.Column="1">
        <TextBlock x:Name="ThemeResourceBindingText"
                   Text="SetThemeResourceBinding updates when the theme changes." />
    </Border>
</Grid>
--- c#
// One-time lookup: the brushes are resolved once and don't update when the theme changes.
OneTimeLookupBorder.Background = (Brush)Application.Current.Resources["AccentFillColorDefaultBrush"];
OneTimeLookupText.Foreground = (Brush)Application.Current.Resources["TextOnAccentFillColorPrimaryBrush"];

// Theme resource binding: the code equivalent of {ThemeResource Key}.
// The brushes are re-resolved whenever the element's ActualTheme changes.
ThemeResourceBindingBorder.SetThemeResourceBinding(Border.BackgroundProperty, "AccentFillColorDefaultBrush");
ThemeResourceBindingText.SetThemeResourceBinding(TextBlock.ForegroundProperty, "TextOnAccentFillColorPrimaryBrush");

private void SwitchThemeButton_Click(object sender, RoutedEventArgs e)
{
    ThemeResourceFromCodeRoot.RequestedTheme = ThemeResourceFromCodeRoot.ActualTheme == ElementTheme.Dark
        ? ElementTheme.Light
        : ElementTheme.Dark;
}

--- header
Using a function in x:Bind
--- xaml
<DatePicker x:Name="DatePickerControl" Header="Select a date" />
<TextBlock Text="{x:Bind FormatDate(DatePickerControl.SelectedDate), Mode=OneWay}" />
--- c#
public string FormatDate(DateTimeOffset? date)
{
    if (date.HasValue)
    {
        return "Selected date is: " + date.Value.ToString("dddd, MMMM d, yyyy");
    }
    else
    {
        return "No date selected";
    }
}

--- header
Using a converter in Binding
--- xaml
<Page...
    xmlns:c="using:YourNamespace">

    <Page.Resources>
        <!-- Declare the converter -->
        <c:EmptyStringToVisibilityConverter x:Key="EmptyStringToVisibilityConverter" />
    </Page.Resources>

    <StackPanel Spacing="8">
        <!-- Input TextBox -->
        <TextBox x:Name="InputTextBox" Header="Enter Text:" Width="300" />

        <!-- TextBlock Visibility Depends on Input Text -->
        <TextBlock Text="The input is not empty."
                    Visibility="{Binding Text, ElementName=InputTextBox, Converter={StaticResource EmptyStringToVisibilityConverter}}" />
    </StackPanel>
</Page>
--- c#
using Microsoft.UI.Xaml.Data;
using Microsoft.UI.Xaml;

namespace YourNamespace
{
    public class EmptyStringToVisibilityConverter : IValueConverter
    {
        // Visibility value when the input string is empty or null
        public Visibility EmptyValue { get; set; } = Visibility.Collapsed;

        // Visibility value when the input string is non-empty
        public Visibility NonEmptyValue { get; set; } = Visibility.Visible;

        public object Convert(object value, Type targetType, object parameter, string language)
        {
            // Return EmptyValue if the input is null or empty, otherwise NonEmptyValue
            return value is string stringValue && !string.IsNullOrEmpty(stringValue) 
                ? NonEmptyValue 
                : EmptyValue;
        }

        public object ConvertBack(object value, Type targetType, object parameter, string language)
        {
            // ConvertBack is not needed and not implemented in this case
            throw new NotImplementedException();
        }
    }
}

--- header
Binding to a view model
--- xaml
<TextBlock Text="Title:" FontWeight="SemiBold" />
<TextBlock Text="{Binding Title}" FontSize="16" />

<TextBlock Text="Description:" FontWeight="SemiBold" />
<TextBlock Text="{Binding Description}" FontSize="16" />
--- c#
using System.ComponentModel; // For INotifyPropertyChanged interface.
using Microsoft.UI.Xaml.Controls; // For Page and other WinUI controls.

namespace YourNamespace
{
    // Main page class
    public sealed partial class YourPage : Page
    {
        // Property to hold the ViewModel instance.
        public ExampleViewModel ViewModel { get; set; }

        public YourPage()
        {
            this.InitializeComponent();

            // Initialize the ViewModel with sample data.
            ViewModel = new ExampleViewModel
            {
                Title = "Welcome to WinUI 3", // Set initial value for Title.
                Description = "This is an example of binding to a view model.", // Set initial value for Description.
            };

            // Set the DataContext of the page to the ViewModel.
            // This makes the ViewModel properties available for binding in XAML.
            DataContext = ViewModel;
        }
    }

    // ViewModel class implementing INotifyPropertyChanged for data binding.
    public class ExampleViewModel : INotifyPropertyChanged
    {
        // Backing field for Title property.
        private string _title = string.Empty;

        // Backing field for Description property.
        private string _description = string.Empty;

        // Property for Title with change notification.
        public string Title
        {
            get => _title; // Return the current value of _title.
            set
            {
                if (_title != value) // Check if the new value is different.
                {
                    _title = value; // Update the backing field.
                    OnPropertyChanged(nameof(Title)); // Notify the UI of the change.
                }
            }
        }

        // Property for Description with change notification.
        public string Description
        {
            get => _description; // Return the current value of _description.
            set
            {
                if (_description != value) // Check if the new value is different.
                {
                    _description = value; // Update the backing field.
                    OnPropertyChanged(nameof(Description)); // Notify the UI of the change.
                }
            }
        }

        // Event to notify subscribers (UI elements) of property changes.
        public event PropertyChangedEventHandler? PropertyChanged;

        // Method to raise the PropertyChanged event.
        // This notifies the UI to update the bound control.
        protected void OnPropertyChanged(string propertyName)
        {
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
        }
    }
}

--- header
Binding with TargetNullValue
--- xaml
<!--TargetNullValue property help handle scenarios where the binding source is null-->
<TextBlock Text="{Binding ViewModel.NullString, Mode=OneWay, TargetNullValue='Anonymous User'}" />
--- c#
public YourPage()
{
    this.InitializeComponent();

    ViewModel = new ExampleViewModel
    {
        NullString = null
    };
                    
    DataContext = ViewModel;
}

--- header
Binding a collection with data templates
--- xaml
<ListView
    x:Name="ListDetailListView"
    ItemsSource="{x:Bind Items}"
    SelectedIndex="0"
    SelectionMode="Single">
    <ListView.ItemTemplate>
        <DataTemplate x:DataType="local:ListDetailItem">
            <StackPanel Padding="4" Spacing="2">
                <TextBlock Text="{x:Bind Title}" FontWeight="SemiBold" />
                <TextBlock Text="{x:Bind DateCreatedFormatted}"
                    Style="{ThemeResource CaptionTextBlockStyle}" />
            </StackPanel>
        </DataTemplate>
    </ListView.ItemTemplate>
</ListView>

<!-- Detail panel bound to the selected item -->
<StackPanel DataContext="{x:Bind ListDetailListView.SelectedItem, Mode=OneWay}">
    <TextBlock Text="{Binding Title}" FontSize="20" FontWeight="SemiBold" />
    <TextBlock Text="{Binding DateCreatedFormatted}"
        Style="{ThemeResource CaptionTextBlockStyle}" />
    <TextBlock Text="{Binding Text}" TextWrapping="Wrap" />
</StackPanel>
--- c#
public class ListDetailItem
{
    public int Id { get; set; }
    public string Title { get; set; }
    public string Text { get; set; }
    public DateTime DateCreated { get; set; }
    public string DateCreatedFormatted => DateCreated.ToString("MMM d, yyyy h:mm tt");
}

// In your page class:
public List<ListDetailItem> Items { get; set; }

public MyPage()
{
    this.InitializeComponent();

    Items = new List<ListDetailItem>
    {
        new ListDetailItem
        {
            Id = 0,
            Title = "Item 1",
            Text = "Lorem ipsum dolor sit amet...",
            DateCreated = new DateTime(2025, 6, 15, 9, 30, 0)
        },
        // Add more items...
    };
}

--- header
Create a DataTemplate in code (experimental)
--- xaml
<ComboBox x:Name="CodeTemplateComboBox" Header="Options" SelectedIndex="0">
    <ComboBox.Items>
        <x:String>Option 1</x:String>
        <x:String>Option 2</x:String>
        <x:String>Option 3</x:String>
    </ComboBox.Items>
</ComboBox>
--- c#
// The factory runs once for every item container that uses the template.
CodeTemplateComboBox.ItemTemplate = new DataTemplate(() =>
{
    FontIcon icon = new FontIcon { Glyph = "\uE734", FontSize = 14 };

    TextBlock text = new TextBlock();
    text.SetBinding(TextBlock.TextProperty, new Binding());

    StackPanel panel = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 8 };
    panel.Children.Add(icon);
    panel.Children.Add(text);
    return panel;
});

--- header
Counter Control with Increment/Decrement Mode
--- xaml
<!-- Generic.xaml -->
<ResourceDictionary 
    xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
    xmlns:local="using:YourNamesapace">

    <!-- Style definition for CounterControl -->
    <Style TargetType="local:CounterControl">
        <Setter Property="Template">
            <Setter.Value>
                <!-- ControlTemplate defines the structure of CounterControl -->
                <ControlTemplate TargetType="local:CounterControl">
                    <StackPanel HorizontalAlignment="Left" Spacing="8">
                        <TextBlock x:Name="CountText" FontSize="20" Text="0" HorizontalAlignment="Center" />
                        <Button x:Name="ActionButton" Content="Increase" HorizontalAlignment="Center" Width="100" />
                    </StackPanel>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
</ResourceDictionary>

<!-- YourPage.xaml -->
<Page ...
      xmlns:controls="using:YourNamesapace">
    <StackPanel Orientation="Horizontal" Spacing="8">
        <controls:CounterControl Mode="Increment" />
        <controls:CounterControl Mode="Decrement" />
    </StackPanel>
</Page>
--- c#
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;

namespace YourNamespace;

// Enum defining the counter mode: Increment or Decrement
public enum CounterMode
{
    Increment,
    Decrement
}

// Custom control class that extends Control
public sealed class CounterControl : Control
{
    // DependencyProperty for storing the count value
    public static readonly DependencyProperty CountProperty =
        DependencyProperty.Register(nameof(Count), typeof(int), typeof(CounterControl), new PropertyMetadata(0));

    // DependencyProperty for determining the counter mode (Increment or Decrement)
    public static readonly DependencyProperty ModeProperty =
        DependencyProperty.Register(nameof(Mode), typeof(CounterMode), typeof(CounterControl), new PropertyMetadata(CounterMode.Increment));

    // Constructor setting the default style key
    public CounterControl()
    {
        this.DefaultStyleKey = typeof(CounterControl);
    }

    // Property to get and set the count value
    public int Count
    {
        get => (int)GetValue(CountProperty);
        set => SetValue(CountProperty, value);
    }

    // Property to get and set the counter mode
    public CounterMode Mode
    {
        get => (CounterMode)GetValue(ModeProperty);
        set => SetValue(ModeProperty, value);
    }

    // Fields for UI elements retrieved from the control template
    private Button? ActionButton;
    private TextBlock? CountText;

    // Method executed when the control's template is applied
    protected override void OnApplyTemplate()
    {
        base.OnApplyTemplate();

        // Retrieve template elements
        ActionButton = GetTemplateChild(nameof(ActionButton)) as Button;
        CountText = GetTemplateChild(nameof(CountText)) as TextBlock;

        // Attach event handler to button if it exists
        if (ActionButton is not null)
        {
            ActionButton.Click += (sender, e) =>
            {
                Count = Mode == CounterMode.Increment ? Count + 1 : Count - 1;
                UpdateUI();
            };

            UpdateButtonText();
        }

        UpdateUI();
    }

    private void UpdateUI()
    {
        if (CountText is not null)
        {
            CountText.Text = Count.ToString();
        }
    }

    private void UpdateButtonText()
    {
        if (ActionButton is not null)
        {
            ActionButton.Content = Mode == CounterMode.Increment ? "Increase" : "Decrease";
        }
    }
}

--- header
Basic Custom Password Box with Validation
--- xaml
<ResourceDictionary
    xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
    xmlns:local="using:YourNamespace">
    
    <Style TargetType="local:ValidatedPasswordBox">
        <Setter Property="IsTabStop" Value="False" />
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="local:ValidatedPasswordBox">
                    <StackPanel Spacing="4">
                        <PasswordBox x:Name="PasswordInput" />
                        <RichTextBlock x:Name="ValidationRichText"
                            AutomationProperties.LiveSetting="Polite"
                            TextWrapping="Wrap"
                            IsTextSelectionEnabled="False"
                            Visibility="Collapsed"/>
                    </StackPanel>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
</ResourceDictionary>

<!-- YourPage.xaml -->
<Page ...
      xmlns:controls="using:YourNamesapace">
    <StackPanel Spacing="8">
        <controls:ValidatedPasswordBox x:Name="PasswordInput" MinLength="8" Width="240" HorizontalAlignment="Left"
                                       Header="Password" PlaceholderText="Enter password..." />
        <Button Content="Submit" IsEnabled="{x:Bind PasswordInput.IsValid, Mode=OneWay}"
                Style="{StaticResource AccentButtonStyle}" Width="240" />
    </StackPanel>
</Page>
--- c#
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Automation.Peers;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Documents;
using Microsoft.UI.Xaml.Media;
using System.Linq;
using Windows.UI;

namespace YourNamespace;

// Custom control for a validated password box
public sealed partial class ValidatedPasswordBox : Control
{
    // Register a dependency property for the Password value.
    // Note: The PropertyMetadata includes a callback (OnPasswordChanged) so that the UI updates
    // whenever the password or related properties change.
    public static readonly DependencyProperty PasswordProperty =
        DependencyProperty.Register(nameof(Password), typeof(string), typeof(ValidatedPasswordBox), new PropertyMetadata(string.Empty, OnPasswordChanged));

    public static readonly DependencyProperty IsValidProperty =
        DependencyProperty.Register(nameof(IsValid), typeof(bool), typeof(ValidatedPasswordBox), new PropertyMetadata(false));

    public static readonly DependencyProperty MinLengthProperty =
        DependencyProperty.Register(nameof(MinLength), typeof(int), typeof(ValidatedPasswordBox), new PropertyMetadata(8, OnPasswordChanged));

    public static readonly DependencyProperty HeaderProperty =
        DependencyProperty.Register(nameof(Header), typeof(string), typeof(ValidatedPasswordBox), new PropertyMetadata(string.Empty, OnPasswordChanged));

    public static readonly DependencyProperty PlaceholderTextProperty =
        DependencyProperty.Register(nameof(PlaceholderText), typeof(string), typeof(ValidatedPasswordBox), new PropertyMetadata(string.Empty, OnPasswordChanged));

    public ValidatedPasswordBox()
    {
        this.DefaultStyleKey = typeof(ValidatedPasswordBox);
    }

    // CLR property wrappers
    public string Password { get => (string)GetValue(PasswordProperty); set => SetValue(PasswordProperty, value); }
    public bool IsValid { get => (bool)GetValue(IsValidProperty); set => SetValue(IsValidProperty, value); }
    public int MinLength { get => (int)GetValue(MinLengthProperty); set => SetValue(MinLengthProperty, value); }
    public string Header { get => (string)GetValue(HeaderProperty); set => SetValue(HeaderProperty, value); }
    public string PlaceholderText { get => (string)GetValue(PlaceholderTextProperty); set => SetValue(PlaceholderTextProperty, value); }

    // Template parts for password input and validation messages
    private PasswordBox? PasswordInput { get; set; }
    private RichTextBlock? ValidationRichText { get; set; }

    protected override void OnApplyTemplate()
    {
        base.OnApplyTemplate();

        PasswordInput = GetTemplateChild(nameof(PasswordInput)) as PasswordBox;
        ValidationRichText = GetTemplateChild("ValidationRichText") as RichTextBlock;

        if (PasswordInput != null)
        {
            PasswordInput.Header = Header;
            PasswordInput.PlaceholderText = PlaceholderText;
            PasswordInput.PasswordChanged += (_, _) => Password = PasswordInput.Password;
        }

        if (ValidationRichText != null)
            ValidationRichText.ActualThemeChanged += (_, _) => UpdateValidationMessages();

        UpdateValidationMessages();
    }

    private static void OnPasswordChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
    {
        ((ValidatedPasswordBox)d).UpdateValidationMessages();
    }

    // Update UI elements based on current password validation
    private void UpdateValidationMessages()
    {
        bool hasMinLength = Password.Length >= MinLength;
        bool hasUppercase = Password.Any(char.IsUpper);
        bool hasNumber = Password.Any(char.IsDigit);

        IsValid = hasMinLength && hasUppercase && hasNumber;

        if (ValidationRichText is null)
            return;

        ValidationRichText.Visibility = string.IsNullOrEmpty(Password) ? Visibility.Collapsed : Visibility.Visible;

        ValidationRichText.Blocks.Clear();

        if (string.IsNullOrEmpty(Password))
            return;

        var paragraph = new Paragraph();

        if (IsValid)
        {
            AddValidationLine(paragraph, "\uE930", "Password is valid", false);
        }
        else
        {
            if (!hasUppercase) AddValidationLine(paragraph, "\uEA39", "Missing uppercase", true);
            if (!hasNumber) AddValidationLine(paragraph, "\uEA39", "Missing number", true);
            if (!hasMinLength) AddValidationLine(paragraph, "\uEA39", "Too short!", true);
        }

        if (paragraph.Inlines.Count > 0)
        {
            ValidationRichText.Blocks.Add(paragraph);
            (FrameworkElementAutomationPeer.FromElement(ValidationRichText)
                 ?? FrameworkElementAutomationPeer.CreatePeerForElement(ValidationRichText))
                .RaiseAutomationEvent(AutomationEvents.LiveRegionChanged);
        }
    }

    private void AddValidationLine(Paragraph paragraph, string iconGlyph, string message, bool isCritical)
    {
        if (paragraph.Inlines.Any())
            paragraph.Inlines.Add(new LineBreak());

        var color = new SolidColorBrush(
            isCritical
                ? (ActualTheme == ElementTheme.Light ? Color.FromArgb(255, 196, 43, 28) : Color.FromArgb(255, 255, 153, 164))
                : (ActualTheme == ElementTheme.Light ? Color.FromArgb(255, 15, 123, 15) : Color.FromArgb(255, 108, 203, 95)));

        paragraph.Inlines.Add(new InlineUIContainer
        {
            Child = new FontIcon { Glyph = iconGlyph, FontSize = 14, Foreground = color }
        });

        paragraph.Inlines.Add(new Run { Text = " ", });
        paragraph.Inlines.Add(new Run { Text = message, Foreground = color });
    }
}

--- header
Temperature Converter UserControl example
--- xaml
<!-- TemperatureConverterControl.xaml -->
<UserControl ...>
    <StackPanel Spacing="8">
        <TextBox Header="Enter Temperature in Celsius" x:Name="InputTextBox" Width="200" PlaceholderText="Celsius" />
        <Button Content="Convert to Fahrenheit" Width="200" Click="Button_Click" />
        <TextBlock x:Name="ResultTextBlock" FontWeight="SemiBold" />
    </StackPanel>
</UserControl>

<!-- Yourpage.xaml -->
<Page ...
      xmlns:local="using:YourNamesapce">
    <Grid>
        <local:TemperatureConverterControl />
    </Grid>
</Page>
--- c#
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;

namespace YourNamesapace;

public sealed partial class TemperatureConverterControl : UserControl
{
    public TemperatureConverterControl()
    {
        this.InitializeComponent();
    }

    private void Button_Click(object sender, RoutedEventArgs e)
    {
        string input = InputTextBox.Text;
        double celsius = 0;

        bool isNumber = double.TryParse(input, out celsius);

        if (isNumber)
        {
            double fahrenheit = (celsius * 9 / 5) + 32;
            ResultTextBlock.Text = "Fahrenheit: " + fahrenheit.ToString("F2") + "°F";
        }
        else
        {
            ResultTextBlock.Text = "Invalid input!";
        }
    }
}

--- header
Conditional elements
--- xaml
<Page
    xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
    xmlns:cond="using:WinUIGallery.ControlPages"
    xmlns:newExp="http://schemas.microsoft.com/winfx/2006/xaml/presentation?cond:FeatureFlagCondition(NewExperience)"
    xmlns:legacy="http://schemas.microsoft.com/winfx/2006/xaml/presentation?cond:FeatureFlagCondition(LegacyMode)">

    <StackPanel Spacing="8">
        <!-- Included only when FeatureFlagCondition.Evaluate("NewExperience") returns true. -->
        <newExp:InfoBar Title="New experience" IsOpen="True" Severity="Success"
                        Message="This InfoBar is included because the 'NewExperience' flag is true." />

        <!-- Included only when FeatureFlagCondition.Evaluate("LegacyMode") returns true. -->
        <legacy:InfoBar Title="Legacy mode" IsOpen="True" Severity="Warning"
                        Message="This InfoBar is included because the 'LegacyMode' flag is true." />
    </StackPanel>
</Page>
--- c#
// Set the active feature flag(s) BEFORE InitializeComponent so the
// XAML parser sees them when it evaluates the conditional elements.
// In a real app these are typically set once at startup (e.g. from
// App.OnLaunched) based on configuration, A/B test assignment, or
// device capability detection. Once parsed, the result for each
// (condition, argument) pair is cached for the lifetime of the
// process - changing a flag later does NOT re-render markup that
// was already parsed.
public sealed partial class MyPage : Page
{
    public MyPage()
    {
        FeatureFlagCondition.FeatureFlags["NewExperience"] = true;
        FeatureFlagCondition.FeatureFlags["LegacyMode"] = false;

        this.InitializeComponent();
    }
}

--- header
Conditional attributes
--- xaml
<Page
    xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:cond="using:WinUIGallery.ControlPages"
    xmlns:newExp="http://schemas.microsoft.com/winfx/2006/xaml/presentation?cond:FeatureFlagCondition(NewExperience)"
    xmlns:legacy="http://schemas.microsoft.com/winfx/2006/xaml/presentation?cond:FeatureFlagCondition(LegacyMode)">

    <!--
        At most ONE of newExp:Background and legacy:Background may evaluate to true at a time.
        If both conditions are true, the XAML parser throws at runtime.
    -->
    <Button Content="Background depends on the active flag"
            newExp:Background="Green"
            legacy:Background="Gray"
            Foreground="White" />
</Page>
--- c#
// Conditional attributes use the same setup. Make sure that, for any
// given attribute, no more than one condition can evaluate to true at
// the same time - if multiple are true the XAML parser will throw at
// runtime.
public sealed partial class MyPage : Page
{
    public MyPage()
    {
        FeatureFlagCondition.FeatureFlags["NewExperience"] = true;
        FeatureFlagCondition.FeatureFlags["LegacyMode"] = false;

        this.InitializeComponent();
    }
}

--- header
Conditional Setters in a Style
--- xaml
<Page
    xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:cond="using:WinUIGallery.ControlPages"
    xmlns:newExp="http://schemas.microsoft.com/winfx/2006/xaml/presentation?cond:FeatureFlagCondition(NewExperience)"
    xmlns:legacy="http://schemas.microsoft.com/winfx/2006/xaml/presentation?cond:FeatureFlagCondition(LegacyMode)">

    <Page.Resources>
        <Style x:Key="ConditionalHeadingStyle" TargetType="TextBlock">
            <!-- Setters can also be qualified with a conditional namespace. -->
            <newExp:Setter Property="FontWeight" Value="SemiBold" />
            <newExp:Setter Property="FontSize" Value="28" />
            <legacy:Setter Property="FontWeight" Value="Normal" />
            <legacy:Setter Property="FontSize" Value="18" />
        </Style>
    </Page.Resources>

    <TextBlock Text="Heading styled with conditional Setters"
               Style="{StaticResource ConditionalHeadingStyle}" />
</Page>
--- c#
// Conditional Setters inside a Style are evaluated when the Style
// resource is first parsed. Set the flags before InitializeComponent
// (or before the resource dictionary that contains the Style is
// loaded) so the parser produces the Style you expect.
public sealed partial class MyPage : Page
{
    public MyPage()
    {
        FeatureFlagCondition.FeatureFlags["NewExperience"] = true;
        FeatureFlagCondition.FeatureFlags["LegacyMode"] = false;

        this.InitializeComponent();
    }
}

--- header
CommandBarFlyout for commands on an in-app object
--- xaml
<Page.Resources>
    <CommandBarFlyout Placement="Right" x:Name="CommandBarFlyout1">
        <AppBarButton Label="Share" Icon="Share" ToolTipService.ToolTip="Share" Click="OnElementClicked" />
        <AppBarButton Label="Save" Icon="Save" ToolTipService.ToolTip="Save" Click="OnElementClicked" />
        <AppBarButton Label="Delete" Icon="Delete" ToolTipService.ToolTip="Delete" Click="OnElementClicked" />
        <CommandBarFlyout.SecondaryCommands>
            <AppBarButton x:Name="ResizeButton1" Label="Resize" Click="OnElementClicked" />
            <AppBarButton x:Name="MoveButton1" Label="Move" Click="OnElementClicked" />
        </CommandBarFlyout.SecondaryCommands>
    </CommandBarFlyout>
</Page.Resources>

<Button x:Name="myImageButton" AutomationProperties.Name="mountain" Padding="0"
    Click="MyImageButton_Click" ContextRequested="MyImageButton_ContextRequested" >
    <Image x:Name="Image1" Height="300" Source="/Assets/SampleMedia/rainier.jpg"/>
</Button>
--- c#
private void ShowMenu(bool isTransient)
{
    FlyoutShowOptions myOption = new FlyoutShowOptions();
    myOption.ShowMode = isTransient ? FlyoutShowMode.Transient : FlyoutShowMode.Standard;
    CommandBarFlyout1.ShowAt(Image1, myOption);
}

private void MyImageButton_ContextRequested(Microsoft.UI.Xaml.UIElement sender, ContextRequestedEventArgs args)
{
    // Show a context menu in standard mode
    // Focus will move to the menu
    ShowMenu(false);
}

private void MyImageButton_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
{
    // Show a context menu in transient mode
    // Focus will not move to the menu
    ShowMenu(true);
}

--- header
Exposing a command in multiple controls using StandardUICommand
--- xaml
<SwipeItem x:Name="DeleteSwipeItem" Background="Red" Command="{x:Bind Command}" CommandParameter="{x:Bind Text}" />

<AppBarButton x:Name="HoverButton" IsTabStop="False" HorizontalAlignment="Right" Visibility="Collapsed" 
 Command="{x:Bind Command}" CommandParameter="{x:Bind Text}" />
--- c#
private void ControlExample_Loaded(object sender, RoutedEventArgs e)
{
    var deleteCommand = new StandardUICommand(StandardUICommandKind.Delete);
    deleteCommand.ExecuteRequested += DeleteCommand_ExecuteRequested;

    DeleteFlyoutItem.Command = deleteCommand;

    for (var i = 0; i < 15; i++)
    {
        collection.Add(new ListItemData { Text = "List item " + i.ToString(), Command = deleteCommand });
    }
}

